// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.eclipse.rdf4j.sail.lmdb.LmdbCompatibilityFixtures.properties;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.Set;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbIndexMetadataCompatibilityTest {
	@TempDir
	Path directory;

	@Test
	void defaultIndexesSurviveCloseAndReopen() throws Exception {
		writeAndClose(null, true);
		assertIndexes(Set.of("spoc", "cspo"));
		writeAndClose(null, false);
		assertIndexes(Set.of("spoc", "cspo"));
	}

	@Test
	void customTermIndexesRemainAuthoritativeUntilExplicitReindex() throws Exception {
		writeAndClose("posc", true);
		assertIndexes(Set.of("spoc", "cspo", "posc"));
		writeAndClose(null, false);
		assertIndexes(Set.of("spoc", "cspo", "posc"));
		writeAndClose("ospc", false);
		assertIndexes(Set.of("spoc", "cspo", "ospc"));
		writeAndClose(null, false);
		assertIndexes(Set.of("spoc", "cspo", "ospc"));
	}

	private void writeAndClose(String termIndexes, boolean add) throws Exception {
		LmdbStoreConfig config = LmdbV6InteroperabilityTest.config(true).setTripleTermIndexes(termIndexes);
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		repository.init();
		var vf = SimpleValueFactory.getInstance();
		var predicate = vf.createIRI("urn:index:predicate");
		var term = vf.createTripleTerm(vf.createIRI("urn:index:inner"), predicate, vf.createLiteral("indexed"));
		try (var connection = repository.getConnection()) {
			if (add) {
				connection.begin();
				connection.add(vf.createIRI("urn:index:outer"), predicate, term);
				connection.commit();
			}
			assertTrue(connection.hasStatement(vf.createIRI("urn:index:outer"), predicate, term, false));
			try (RecordIterator terms = ((ValueStore) repository.getValueFactory()).getTripleTerms(-1, -1, -1)) {
				assertTrue(terms.next() != null);
			}
		} finally {
			repository.shutDown();
		}
	}

	private void assertIndexes(Set<String> terms) throws Exception {
		var properties = properties(directory, "store.properties");
		assertEquals("2", properties.getProperty("version"));
		assertEquals(Set.of("spoc", "posc", "ospc"),
				TripleIndex.parseIndexSpecList(properties.getProperty("triple-indexes")));
		assertEquals(terms, TripleIndex.parseIndexSpecList(properties.getProperty("triple-term-indexes")));
	}
}
